using GraphApi.Models.USR.Parentescos;namespace GraphApi.Services.USR.Parentescos{    /// <summary>    /// Define las operaciones de negocio y persistencia para Parentescos.    /// </summary>    public interface IParentescosService    {        /// <summary>        /// Obtiene la lista de Parentescos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadParentescos>> GetParentescos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Parentescos con filtros opcionales.        /// </summary>        /// <param name="parentescoID">Filtro opcional para ParentescoID.</param>        /// <param name="parentesco">Filtro opcional para Parentesco.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetParentescosDynamic(            int? parentescoID,            string? parentesco,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Parentesco.        /// </summary>        /// <param name="objInput">Datos para crear el Parentesco.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadParentescos> CreateParentescos(            clCreateParentescos objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Parentesco.        /// </summary>        /// <param name="objInput">Datos para actualizar el Parentesco, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadParentescos?> UpdateParentescos(            clUpdateParentescos objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Parentesco por su ID.        /// </summary>        /// <param name="nParentescosID">ID del Parentesco a eliminar.</param>        Task<bool> DeleteParentescos(int nParentescosID);    }}